def has_cycle(graph):
    # Collect all nodes: keys and all successors
    nodes = set(graph.keys())
    for succs in graph.values():
        nodes.update(succs)

    # 0 = unvisited, 1 = visiting (in recursion stack), 2 = visited (finished)
    state = {}

    def dfs(u):
        if state.get(u, 0) == 1:
            # Found a node in the current recursion stack -> cycle
            return True
        if state.get(u, 0) == 2:
            # Already fully processed, no cycle from here
            return False
        state[u] = 1  # mark as visiting
        for v in graph.get(u, []):
            if dfs(v):
                return True
        state[u] = 2  # mark as finished
        return False

    for node in nodes:
        if state.get(node, 0) == 0:
            if dfs(node):
                return True
    return False

